R('m10', 8, 11, 'c', 'a', 'adc', 2, 'Độ chính xác của đầu ra ADC xấp xỉ liên tiếp phần lớn phụ thuộc vào:', 'Accuracy of the output of a successive approximation ADC is largely dependent on:',
  [('độ phân giải', 'resolution'), ('điện áp nguồn', 'supply voltage'), ('thời gian chuyển đổi', 'conversion time')],
  'Sai số lượng tử hoá của ADC là ±½ LSB = ±½·Vref/2ⁿ nên độ chính xác chủ yếu do độ phân giải (số bit n) quyết định; thời gian chuyển đổi (10 đến 100 µs, Tooley tr.47) chỉ quyết định tốc độ. Sách in khoá (c); site dùng (a) theo lý thuyết ADC, nên hỏi giảng viên nếu đề thi dùng khoá in.',
  'The quantisation error of an ADC is ±½ LSB = ±½·Vref/2ⁿ so accuracy is set mainly by the resolution (number of bits n); the conversion time (10 to 100 µs, Tooley p.47) only sets the speed. The book prints key (c); the site uses (a) from ADC theory, so check with the lecturer if the exam follows the printed key.')
R('m05', 8, 12, 'b', 'b', 'arinc429', 1, 'Có thể nối bao nhiêu máy thu vào một nguồn phát trên bus ARINC 429?', 'How many receivers can be attached to one transmit source in the ARINC 429 bus?',
  ['10', '20', '32'], 'Một cặp dây ARINC 429 có một máy phát và tối đa 20 máy thu.', 'An ARINC 429 pair has one transmitter and up to 20 receivers.', ev=['supports up to 20'])
R('m15', 8, 13, 'b', 'b', 'info', 1, 'Đặc tả nào liên quan đến hệ thống mạng thông tin cabin hành khách?', 'Which one of the following specifications relates to passenger cabin information network systems?',
  ['ARINC 429', 'ARINC 628', 'ARINC 629'], 'ARINC 628 là chuẩn hệ thống giải trí và thông tin cabin; ARINC 429 và 629 là bus dữ liệu điện tử hàng không.', 'ARINC 628 is the cabin entertainment and information systems standard; ARINC 429 and 629 are avionics data buses.', ev=['ARINC 628'])
R('m07', 8, 16, 'c', 'c', 'do178', 1, 'Các khía cạnh phần mềm của hệ thống máy bay phải được bảo đảm là an toàn và đủ điều kiện bay. Quá trình này được gọi là:', 'Software aspects of an aircraft system must be assured to be safe and airworthy. This process is known as:',
  [('phê duyệt', 'approval'), ('đánh giá', 'evaluation'), ('chứng nhận', 'certification')], 'Quá trình bảo đảm phần mềm an toàn và đủ điều kiện bay là chứng nhận (certification) theo DO-178B/ED-12B.', 'The process of assuring that software is safe and airworthy is certification under DO-178B/ED-12B.', ev=['software certification'])
R('m09', 8, 19, 'a', 'a', 'esd', 1, 'Linh kiện nhạy tĩnh điện (ESD) phải được cất giữ trong:', 'Electrostatic sensitive devices (ESD) should be stored in:',
  [('túi chống tĩnh điện', 'anti-static bags'), ('thùng kim loại', 'metal storage bins'), ('hộp nhựa cách điện', 'insulated plastic containers')], 'Túi chống tĩnh điện (dẫn điện nhẹ) giữ mọi chân cùng điện thế và không tích điện; hộp nhựa cách điện lại tích điện.', 'Anti-static bags (slightly conductive) keep all pins at one potential and do not build charge; insulated plastic builds static.', ev=['anti-static'])
